import { flattenInvalidFieldPaths } from '@/functions/analytics/flattenReactHookFormErrors';
import { scrollToInvalidBrokerField } from '@/functions/analytics/scrollToInvalidBrokerField';
import { capitalizeFirstLetter, numberToWords } from '@/functions/formaters/numberToWords';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import posthog from 'posthog-js';
import type { FieldErrors } from 'react-hook-form';

const SURFACE = 'crm_broker_cedente';

const CEDENTE_FIELD_LABELS: Record<string, string> = {
    nome: 'Nome completo',
    cpf: 'CPF',
    rg: 'RG',
    orgao_exp_rg: 'Órgão expedidor',
    data_nascimento: 'Data de nascimento',
    nome_pai: 'Nome do pai',
    nome_mae: 'Nome da mãe',
    profissao: 'Profissão',
    nacionalidade: 'Nacionalidade',
    estado_civil: 'Estado civil',
    razao_social: 'Razão social',
    cnpj: 'CNPJ',
    representante_legal_id: 'Representante legal',
    representante_legal: 'Representante legal',
    cep: 'CEP',
    logradouro: 'Logradouro',
    numero: 'Número',
    complemento: 'Complemento',
    bairro: 'Bairro',
    municipio: 'Município',
    estado: 'Estado',
    telefone: 'Telefone',
    email: 'E-mail',
    banco: 'Banco',
    agencia: 'Agência',
    conta: 'Conta',
    pix: 'PIX',
    percentual_cessao: 'Percentual de cessão',
};

export function getCedenteFieldLabel(path: string): string {
    const leaf = path.split('.').pop() ?? path;
    return CEDENTE_FIELD_LABELS[leaf] ?? leaf.replace(/_/g, ' ');
}

export function formatCedenteInvalidFieldSummary(paths: string[], maxLabels = 4): string {
    const labels = paths.map(getCedenteFieldLabel);
    const unique = Array.from(new Set(labels));
    if (unique.length <= maxLabels) return unique.join(', ');
    return `${unique.slice(0, maxLabels).join(', ')} e mais ${unique.length - maxLabels}`;
}

export function captureCedenteFormEvent(
    event: string,
    payload: Record<string, unknown> = {},
) {
    posthog.capture(event, {
        surface: SURFACE,
        ...payload,
    });
}

export function buildCedenteValidationFailureView(errors: FieldErrors) {
    const invalidPaths = flattenInvalidFieldPaths(errors);
    const fallbackPaths = Object.keys(errors);
    const paths = invalidPaths.length > 0 ? invalidPaths : fallbackPaths;
    const invalidCount = paths.length;
    const firstPath = paths[0];
    const labelSummary = formatCedenteInvalidFieldSummary(paths);
    const invalidFieldLabels = paths.map(getCedenteFieldLabel);
    const title = `${capitalizeFirstLetter(numberToWords(invalidCount))} ${invalidCount === 1 ? 'campo precisa' : 'campos precisam'} de correção`;

    return {
        paths,
        firstPath,
        invalidCount,
        labelSummary,
        invalidFieldLabels,
        title,
    };
}

/**
 * Toast with PT labels, PostHog funnel props, scroll + focus on first invalid field.
 */
export function handleCedenteFormValidationFailure(params: {
    errors: FieldErrors;
    setFocus?: (name: string) => void;
    formTipo: 'PF' | 'PJ';
    mode?: 'create' | 'edit';
    /** e.g. open accordion before scrolling (EditCedenteForm) */
    onBeforeScroll?: (firstPath: string) => void;
}) {
    const { errors, setFocus, formTipo, mode = 'create', onBeforeScroll } = params;
    const view = buildCedenteValidationFailureView(errors);

    captureCedenteFormEvent('crm_broker_cedente_form_validation_failed', {
        form_tipo: formTipo,
        mode,
        invalid_field_paths: view.paths,
        invalid_field_labels: view.invalidFieldLabels,
        invalid_count: view.invalidCount,
    });
    captureCedenteFormEvent('crm_broker_cedente_form_error_shown', {
        form_tipo: formTipo,
        mode,
        context: 'client_validation_toast',
        invalid_count: view.invalidCount,
        invalid_field_paths: view.paths,
        invalid_field_labels: view.invalidFieldLabels,
    });

    sendToastMessage({
        title: view.title,
        description: view.labelSummary,
        type: 'error',
    });

    if (!view.firstPath) return;

    onBeforeScroll?.(view.firstPath);

    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            scrollToInvalidBrokerField(view.firstPath!, setFocus);
        });
    });
}

