import CustomCheckbox from '@/components/CrmUi/Checkbox';
import CustomSkeleton from '@/components/CrmUi/CustomSkeleton';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { CEDENTE_BANCO_OPTIONS, CEDENTE_ESTADO_OPTIONS } from '@/constants/cedentes';
import {
    AGENCIA_CLEAVE_OPTIONS,
    CEP_CLEAVE_OPTIONS,
    CHAVE_ALEATORIA_CLEAVE_OPTIONS,
    CNPJ_CLEAVE_OPTIONS,
    CONTA_CLEAVE_OPTIONS,
    TELEFONE_CLEAVE_OPTIONS,
} from '@/constants/cleave-options';
import { QueryKeys } from '@/constants/query-keys';
import { ProductCombobox, ProductSelect } from '@/design-system';
import { resolveOficioCedentePrefill } from '@/functions/broker/oficio-cedente-prefill';
import { handleCedenteFormValidationFailure, captureCedenteFormEvent } from '@/functions/analytics/cedenteFormValidationUx';
import { applyCedenteFullSchemaValidation } from '@/functions/broker/applyCedenteFullSchemaValidation';
import { debounce } from '@/functions/debounce';
import { CPFAndCNPJMask } from '@/functions/formaters/CPFAndCNPJInput';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { reverificarExigenciasProposta } from '@/functions/propostas/reverificar-exigencias-proposta';
import { sleep } from '@/functions/timer/sleep';
import {
    useOficioLinkedCedentesQuery,
    useRegisteredCedentesListQuery,
} from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { usePJDataQuery } from '@/hooks/queries/use-direct-data';
import { createNewCedente } from '@/services/BrokerServices';
import { fetchAddressByCep } from '@/services/cep/fetchAddressByCep';
import { linkCedenteToExtratoWithAutoEsteira } from '@/services/oficios';
import { PixOption } from '@/types/pix';
import queryClient from '@/utils/queryClient';
import { zodResolver } from '@hookform/resolvers/zod';
import { useMutation, useQuery } from '@tanstack/react-query';
import { AxiosError } from 'axios';
import Cleave from 'cleave.js/react';
import {
    AtSign,
    BadgeAlert,
    BadgeCheck,
    Banknote,
    Building,
    Building2,
    CreditCard,
    Home,
    HousePlus,
    IdCard,
    Landmark,
    LoaderCircle,
    Map,
    MapPin,
    Percent,
    Phone,
    Plus,
    Scale,
    TriangleAlert,
    User,
} from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { Controller, FieldErrors, useForm } from 'react-hook-form';
import type { ICedenteRegistrationShellProps } from '../../../interfaces/cedenteRegistrationShell';
import { PixTypeSelect } from '../PixTypeSelect';
import {
    buildRepresentanteLegalOptions,
} from './cedenteRegistrationFormOptions';
import {
    CEDENTE_ADD_REPRESENTANTE_BUTTON_CLASS,
    CEDENTE_FIELD_ERROR_CLASS,
    CEDENTE_FIELD_LABEL_CLASS,
    CEDENTE_FORM_GRID_CLASS,
    CEDENTE_FORM_SHELL_CLASS,
    CedenteCepLookupStatus,
    CedenteFormActions,
    CedenteFormBackButton,
    CedenteFormNotice,
    CedenteFormSection,
    CedenteFormSectionHeader,
    getCedenteFormInputClass,
} from './cedenteRegistrationFormUi';
import {
    PJ_PARTIAL_CREATE_REQUIRED_FIELDS,
    buildCedenteCreateFormFields,
    pjCedenteFormSchema,
    pjCedentePartialSaveSchema,
    type PjCedenteFormValues,
} from './schemas/cedente-form-schemas';
import { useCedenteRegistrationDeps } from './utils/useCedenteRegistrationDeps';

const RegisterPJCedenteForm = ({
    closeModal,
    backStepForm,
    openRegisterPFForm,
    registrationShell,
}: {
    closeModal: () => void;
    backStepForm?: () => void;
    openRegisterPFForm?: () => void;
    registrationShell?: ICedenteRegistrationShellProps;
}) => {
    const { extratoId, cessionPercentageAvailable } = useCedenteRegistrationDeps(registrationShell);

    // ==================
    // # States
    // ==================
    const [isFullPercentage, setIsFullPercentage] = useState(() =>
        cessionPercentageAvailable === 100 ? true : false,
    );

    // ==================
    // # React Queries
    // ==================
    const { data: registeredCedentesList, isLoading: isLoadingRegisteredCedentesList } =
        useRegisteredCedentesListQuery();
    const { data: extratoData } = useQuery(useExtratoDataQueryOptions(extratoId));
    const { data: linkedCedentesList, isSuccess: isLinkedCedentesLoaded } =
        useOficioLinkedCedentesQuery(extratoId);
    const vigenteProposalData = extratoData?.propostas?.find((p) => p.vigente);
    const hasLinkedCedente = (linkedCedentesList?.length ?? 0) > 0;

    // ==================
    // # States
    // ==================
    const [cnpjToSearch, setCnpjToSearch] = useState<string>('');
    const [pixOption, setPixOption] = useState<PixOption>('Telefone');
    const [isSearchingCep, setIsSearchingCep] = useState(false);
    const [oficioPrefillNotice, setOficioPrefillNotice] = useState<string | null>(null);
    const lastCepLookupDigitsRef = useRef<string | null>(null);
    const didPrefillFromOficioRef = useRef(false);
    const nameLockedFromOficioRef = useRef(false);
    const saveIntentRef = useRef<'partial' | 'finalize'>('partial');

    // ==================
    // # Direct Data Query
    // ==================
    const { data: pjData, isLoading: isLoadingPJData } = usePJDataQuery(cnpjToSearch);

    // ==================
    // # Hook Form
    // ==================
    const {
        register,
        handleSubmit,
        control,
        setValue,
        setFocus,
        getValues,
        setError,
        clearErrors,
        watch,
        formState: { errors, dirtyFields },
    } = useForm<PjCedenteFormValues>({
        resolver: zodResolver(pjCedentePartialSaveSchema),
        shouldFocusError: false,
        defaultValues: {
            tipo: 'PJ',
            telefone: '',
            cep: '',
            cnpj: '',
            razao_social: '',
            representante_legal_id: '',
            bairro: '',
            email: '',
            estado: '',
            logradouro: '',
            complemento: '',
            municipio: '',
            agencia: '',
            conta: '',
            pix: '',
            banco: '',
            percentual_cessao: String(cessionPercentageAvailable),
        },
    });

    // const [fetchingCedentePfList, cedentePfListTransition] = useTransition();
    let createCedenteToastId: string | number | undefined;
    const debouncedSetCnpjToSearch = useMemo(
        () =>
            debounce((cnpj: string) => {
                if (cnpj.length === 18) {
                    setCnpjToSearch(cnpj);
                } else {
                    setCnpjToSearch('');
                }
            }, 800),
        [],
    );

    // ===============
    // # Const
    // ===============
    const registeredCedentesPFList = useMemo(() => {
        return registeredCedentesList?.filter((cedente) => cedente.tipo === 'PF') || [];
    }, [registeredCedentesList]);
    const adaptedFilteredList = useMemo(() => {
        return registeredCedentesPFList
            .map((cedente) => ({
                id: cedente.id,
                nome: cedente.nome,
            }))
            .sort((a, b) => a.nome.localeCompare(b.nome));
    }, [registeredCedentesPFList]);
    const representanteLegalOptions = useMemo(
        () => buildRepresentanteLegalOptions(adaptedFilteredList),
        [adaptedFilteredList],
    );

    // ==================
    // # Mutations
    // ==================
    const createCedente = useMutation({
        mutationFn: async (paramObj: { data: PjCedenteFormValues; formFields: string[] }) => {
            const { data, formFields } = paramObj;
            const req = await createNewCedente(data, formFields);
            return req;
        },
        onMutate: async () => {
            const isPartial = saveIntentRef.current === 'partial';
            createCedenteToastId = sendToastMessage({
                title: isPartial ? 'Salvando dados...' : 'Cadastrando cedente...',
                description: 'Este processo pode levar alguns segundos.',
                type: 'loading',
            });
            captureCedenteFormEvent(
                isPartial
                    ? 'crm_broker_cedente_form_save_partial_started'
                    : 'crm_broker_cedente_form_finalize_started',
                { form_tipo: 'PJ', mode: 'create' },
            );
        },
        onError: (error) => {
            if (error instanceof AxiosError) {
                captureCedenteFormEvent(
                    saveIntentRef.current === 'partial'
                        ? 'crm_broker_cedente_form_save_partial_failed'
                        : 'crm_broker_cedente_form_finalize_failed',
                    { form_tipo: 'PJ', mode: 'create', reason: 'api' },
                );
                sendToastMessage({
                    title: error.response?.data.detail || 'Erro ao realizar cadastro',
                    type: 'error',
                    previousToastId: createCedenteToastId,
                });
            }
        },
        onSuccess: async (data, paramObj) => {
            const { data: formData } = paramObj;
            const isPartial = saveIntentRef.current === 'partial';
            captureCedenteFormEvent(
                isPartial
                    ? 'crm_broker_cedente_form_save_partial_succeeded'
                    : 'crm_broker_cedente_form_finalize_succeeded',
                { form_tipo: 'PJ', mode: 'create' },
            );
            await handleLinkRegisteredCedente(
                data.id as string,
                formData,
                createCedenteToastId,
                isPartial,
            );
        },
    });

    const handleLinkRegisteredCedente = async (
        idCedente: string,
        formValues: PjCedenteFormValues,
        previousToastId?: string | number,
        isPartial = false,
    ) => {
        // Vincula o cedente recém criado
        if (cessionPercentageAvailable > 0) {
            const payload = {
                cedente: idCedente,
                percentual_cessao: formValues.percentual_cessao,
            } as Record<string, string>;

            let linkingToastId: string | number | undefined;
            try {
                linkingToastId = sendToastMessage({
                    title: 'Vinculando cedente...',
                    type: 'loading',
                    previousToastId,
                });
                await linkCedenteToExtratoWithAutoEsteira(extratoId, payload);

                const awaitSyncDataToastId = sendToastMessage({
                    title: 'Aguardando sincronização de dados...',
                    type: 'loading',
                    previousToastId: linkingToastId,
                });

                await sleep(4);
                const updatingListToastId = sendToastMessage({
                    title: 'Atualizando lista de cedentes.',
                    type: 'loading',
                    previousToastId: awaitSyncDataToastId,
                });

                await queryClient.invalidateQueries({
                    queryKey: [QueryKeys.cedentes.linkedExtratoCedentes], type: "all"
                });
                await queryClient.invalidateQueries({
                    queryKey: [QueryKeys.oficios.item, extratoId],
                });
                await queryClient.invalidateQueries({
                    queryKey: [QueryKeys.cedentes.linkedEsteirasCedente, idCedente],
                });
                sendToastMessage({
                    title: isPartial
                        ? 'Dados salvos. Você pode continuar preenchendo.'
                        : 'Lista de cedentes atualizada.',
                    type: 'success',
                    previousToastId: updatingListToastId,
                });

                await reverificarExigenciasProposta(queryClient, vigenteProposalData?.uuid);
            } catch (error) {
                if (error instanceof AxiosError) {
                    sendToastMessage({
                        title: error.response?.data.detail || 'Erro ao vincular cedente',
                        type: 'error',
                        previousToastId: linkingToastId || previousToastId,
                    });
                }
            }
        } else if (isPartial && previousToastId) {
            sendToastMessage({
                title: 'Dados salvos. Você pode continuar preenchendo.',
                type: 'success',
                previousToastId,
            });
        }
        queryClient.invalidateQueries({ queryKey: [QueryKeys.cedentes.list] });
        closeModal();
    };

    // função que atualiza dados do formulário pelo CEP digitado
    const searchCep = async (cep: string) => {
        const digits = cep.replace(/\D/g, '');

        if (digits.length !== 8) return;
        if (lastCepLookupDigitsRef.current === digits && isSearchingCep) return;

        try {
            setIsSearchingCep(true);
            const result = await fetchAddressByCep(digits);
            lastCepLookupDigitsRef.current = digits;
            setValue('municipio', result.city, { shouldDirty: true });
            setValue('estado', result.state, { shouldDirty: true });
            setValue('bairro', result.neighborhood, { shouldDirty: true });
            setValue('logradouro', result.street, { shouldDirty: true });
        } catch {
            sendToastMessage({
                title: 'Erro ao buscar CEP',
                description: 'Não foi possível buscar os dados do CEP informado.',
                type: 'error',
            });
        } finally {
            setIsSearchingCep(false);
        }
    };

    // função de submit para o formulário de criação de cedente
    const onSubmit = async (
        data: PjCedenteFormValues,
        intent: 'partial' | 'finalize' = 'partial',
    ) => {
        saveIntentRef.current = intent;

        let modifiedFormFields = buildCedenteCreateFormFields(
            data as unknown as Record<string, unknown>,
            dirtyFields,
            PJ_PARTIAL_CREATE_REQUIRED_FIELDS,
        );

        // Garante que 'tipo' sempre seja incluído
        if (!modifiedFormFields.includes('tipo')) {
            modifiedFormFields = [...modifiedFormFields, 'tipo'];
        }

        if (data.telefone) {
            data.telefone = data.telefone.replace(/\D/g, ''); // remove tudo que não for dígito
        }

        if (data.numero) {
            data.numero = String(data.numero);
        }

        await createCedente.mutateAsync({
            data,
            formFields: modifiedFormFields,
        });
    };

    function onFormFailure(formErrors: FieldErrors<PjCedenteFormValues>) {
        captureCedenteFormEvent('crm_broker_cedente_form_save_partial_failed', {
            form_tipo: 'PJ',
            mode: 'create',
            reason: 'client_validation',
        });
        handleCedenteFormValidationFailure({
            errors: formErrors,
            formTipo: 'PJ',
            mode: 'create',
            setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
        });
    }

    function onSavePartial(data: PjCedenteFormValues) {
        return onSubmit(data, 'partial');
    }

    async function onFinalizeClick() {
        const values = getValues();
        const isValid = applyCedenteFullSchemaValidation({
            schema: pjCedenteFormSchema,
            values,
            setError,
            clearErrors,
            formTipo: 'PJ',
            mode: 'create',
            setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
        });
        if (!isValid) return;
        await onSubmit(values, 'finalize');
    }

