351	            } catch (error) {
352	                if (error instanceof AxiosError) {
353	                    sendToastMessage({
354	                        title: error.response?.data.detail || 'Erro ao vincular cedente',
355	                        type: 'error',
356	                        previousToastId: linkingToastId || previousToastId,
357	                    });
358	                }
359	            }
360	        } else if (isPartial && previousToastId) {
361	            sendToastMessage({
362	                title: 'Dados salvos. Você pode continuar preenchendo.',
363	                type: 'success',
364	                previousToastId,
365	            });
366	        }
367	
368	        queryClient.invalidateQueries({ queryKey: [QueryKeys.cedentes.list] });
