387	        } catch {
388	            sendToastMessage({
389	                title: 'Erro ao buscar CEP',
390	                description: 'Não foi possível buscar os dados do CEP informado.',
391	                type: 'error',
392	            });
393	        } finally {
394	            setIsSearchingCep(false);
395	        }
396	    };
