function onFormFailure(formErrors: FieldErrors<PfCedenteFormValues>) {
    captureCedenteFormEvent('crm_broker_cedente_form_save_partial_failed', {
        form_tipo: 'PF',
        mode: mode === 'edit' ? 'edit' : 'create',
        reason: 'client_validation',
    });
    handleCedenteFormValidationFailure({
        errors: formErrors,
        formTipo: 'PF',
        mode: mode === 'edit' ? 'edit' : 'create',
        setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
    });
}

function onSavePartial(data: PfCedenteFormValues, event?: React.BaseSyntheticEvent) {
    return onSubmit(data, event, 'partial');
}

async function onFinalizeClick() {
    const values = getValues();
    const isValid = applyCedenteFullSchemaValidation({
        schema: pfCedenteFormSchema,
        values,
        setError,
        clearErrors,
        formTipo: 'PF',
        mode: mode === 'edit' ? 'edit' : 'create',
        setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
    });
    if (!isValid) return;
    await onSubmit(values, undefined, 'finalize');
}

