    hydratedRepresentanteIdRef.current = null;
}, [representanteLegalId]);

useEffect(() => {
    if (mode !== 'edit' || !representanteData) return;
    const incomingId = String(representanteData.id || representanteLegalId || '');
    if (!shouldHydrateCedenteForm(hydratedRepresentanteIdRef.current, incomingId)) return;

    setPixOption(
        validationSelectPix(
            representanteData.informacoes_bancarias?.pix || '',
        ) as unknown as PixOption,
    );
    const mapped = mapCedenteDataToFormValues(representanteData, 'pf');
    for (const [key, value] of Object.entries(mapped)) {
        setValue(key as keyof PfCedenteFormValues, value);
    }
    hydratedRepresentanteIdRef.current = incomingId;
}, [representanteData, mode, representanteLegalId, setValue]);

useEffect(() => {
    if (mode === 'create' && isFullPercentage && cessionPercentageAvailable > 0) {
        setValue('percentual_cessao', '100');
    }
}, [mode, isFullPercentage, cessionPercentageAvailable, setValue]);

useEffect(() => {
