import React from 'react';
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { RegisterModalWrapper } from '@/components/Forms/Broker/RegisterModalWrapper';
import {
    resolveCedenteDialogTitle,
    type CedenteDialogStep,
} from '@/functions/broker/cedente-dialog-title';
import type { EnsureCedenteSuggestionMatch } from '@/services/oficios';
import { cn } from '@/lib/utils';

interface DialogBrokerProps {
    triggerButton?: React.ReactNode;
    openingMode?: 'create' | 'edit' | 'createFromPj';
    readonly?: boolean;
    /** Pre-selects a registered cedente in the link step and pins it to the top. */
    suggestedCedenteId?: string | null;
    suggestedNome?: string | null;
    suggestedNotice?: string | null;
    suggestedMatch?: EnsureCedenteSuggestionMatch | null;
    defaultOpen?: boolean;
    /** `broker-sheet` alinha o modal aos tokens da gaveta do broker. */
    surface?: 'default' | 'broker-sheet';
}

export const DialogBroker = ({
    triggerButton,
    openingMode = 'create',
    readonly = false,
    suggestedCedenteId,
    suggestedNome,
    suggestedNotice,
    suggestedMatch,
    defaultOpen = false,
    surface = 'default',
}: DialogBrokerProps) => {
    const isBrokerSheet = surface === 'broker-sheet';
    const [isModalOpen, setIsModalOpen] = React.useState(defaultOpen);
    const [currentStep, setCurrentStep] = React.useState<CedenteDialogStep>('link');

    function displayTitleMessage() {
        return resolveCedenteDialogTitle({ openingMode, readonly, step: currentStep });
    }

    function handleOpenChange(open: boolean) {
        setIsModalOpen(open);
        if (!open) setCurrentStep('link');
    }

    return (
        <Dialog open={isModalOpen} onOpenChange={handleOpenChange}>
            <DialogTrigger asChild>
                {triggerButton ?? (
                    <Button
                        variant="ghost"
                        className="cursor-pointer text-center text-app-default transition-colors duration-300 hover:text-app-default hover:underline"
                    >
                        vincular cedente
                    </Button>
                )}
            </DialogTrigger>
            <DialogContent
                className={cn(
                    'flex h-[85vh] w-11/12 flex-col border p-5 md:w-4/5 lg:max-w-180 lg:p-10',
                    isBrokerSheet
                        ? 'rounded-2xl border-celer-line bg-celer-paper shadow-xl dark:border-white/10 dark:bg-boxdark lg:p-6'
                        : 'rounded-md bg-boxdark dark:border-strokedark dark:bg-boxdark',
                )}
            >
                <DialogHeader>
                    <DialogTitle
                        className={cn(
                            'text-xl',
                            isBrokerSheet
                                ? 'font-semibold text-celer-strong dark:text-celer-paper'
                                : 'text-title',
                        )}
                    >
                        {displayTitleMessage()}
                    </DialogTitle>
                </DialogHeader>
                <RegisterModalWrapper
                    closeModal={() => handleOpenChange(false)}
                    openingMode={openingMode}
                    onStepChange={setCurrentStep}
                    suggestedCedenteId={suggestedCedenteId}
                    suggestedNome={suggestedNome}
                    suggestedNotice={suggestedNotice}
                    suggestedMatch={suggestedMatch}
                />
            </DialogContent>
        </Dialog>
    );
};

