5	import { GerencialOficioSectionSkeleton } from '@/app/crm/gerencial-broker/_components/shared/GerencialOficioSectionSkeleton';
6	import {
7	    GERENCIAL_OFICIO_SECTION_CLASS,
8	    gerencialOficioSectionStyle,
9	} from '@/app/crm/gerencial-broker/_components/shared/GerencialOficioSectionCard';
10	import { useIsGerencialOficioDetail } from '@/app/crm/gerencial-broker/_hooks/useIsGerencialOficioDetail';
11	import { CollaborationConflictModal } from '@/components/Collaboration/CollaborationConflictModal';
12	import { CollaborationProvider } from '@/components/Collaboration/CollaborationContext';
13	import { buildCollaborationContextValue } from '@/components/Collaboration/build-collaboration-context-value';
14	import {
