21	import { OficioDetailsSkeleton } from '@/components/Skeletons/Broker/OficioDetailsSkeleton';
22	import { ProposalHistorySkeleton } from '@/components/Skeletons/Broker/ProposalHistorySkeleton';
23	import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
24	import { Button } from '@/components/ui/button';
25	import { ProposalCreationTour } from '@/components/ui/proposal-creation-tour';
26	import { APP_ROUTES } from '@/constants/app-routes';
27	import { QueryKeys } from '@/constants/query-keys';
28	import { hasCessionarioLink } from '@/functions/broker/cedente-cession-percentage';
29	import { resolveOficioSectionLockState } from '@/functions/broker/oficio-lock-state';
30	import { DocsSliderContextProvider } from '@/context/DocsSliderContext';
