34	import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
35	import { useResourceCollaboration } from '@/hooks/useResourceCollaboration';
36	import { getAccessibleHosts, Host } from '@/services/host';
37	import { useBrokerStore } from '@/store/useBroker';
38	import { useUserInfoStore } from '@/store/userInfo';
39	import { isProposalSemSmartblock } from '@/functions/propostas/is-proposal-sem-smartblock';
40	import type { CollaborationStateChangedEvent } from '@/types/collaboration';
41	import { getTenantFromUrl } from '@/utils/getHostFromUrl';
42	import queryClient from '@/utils/queryClient';
43	import { useQuery, useSuspenseQuery } from '@tanstack/react-query';
44	import { AxiosError } from 'axios';
45	import { AlertTriangle, ChevronLeft, Info, LoaderCircle } from 'lucide-react';
46	import Link from 'next/link';
47	import { lazy, Suspense, useCallback, useEffect, useMemo, useState } from 'react';
48	import posthog from 'posthog-js';
49	import { BrokerExigenciasViewer } from './BrokerExigenciasViewer';
50	import BrokerOficioStepper from './BrokerOficioStepper';
51	import { BrokerCommentsSection } from './CommentsSection';
52	import {
53	    OFICIO_COMMENTS_PANEL_CLASS,
54	    OFICIO_COMMENTS_STICKY_ASIDE_CLASS,
55	} from './oficio-comments-sticky-layout';
56	import ProposalHistory from './ProposalHistory';
57	import { SemSmartblockAlert } from '@/components/CRM/Broker/SemSmartblockAlert';
58	import { cn } from '@/lib/utils';
59	
60	// Lazy load heavy components
61	const BrokerCedenteForm = lazy(() => import('@/components/Forms/Broker/BrokerCedenteForm'));
62	const BrokerSlider = lazy(() => import('@/components/Sliders/BrokerSlider'));
63	const DocumentsSection = lazy(() =>
64	    import('@/app/crm/broker/[id]/_components/DocumentsSection').then((module) => ({ default: module.DocumentsSection })),
65	);
66	const ReadOnlyOficioInfoForm = lazy(() =>
67	    import('@/components/Forms/ReadOnlyOficioInfoForm').then((module) => ({
68	        default: module.ReadOnlyOficioInfoForm,
69	    })),
70	);
71	const NewEditOficioBrokerForm = lazy(() => import('@/components/Forms/NewEditOficioBrokerForm'));
72	
73	export const BrokerOficioDetails = ({ id }: { id: string }) => {
74	    const isGerencialOficioDetail = useIsGerencialOficioDetail();
75	    const sectionFallback = isGerencialOficioDetail ? (
76	        <GerencialOficioSectionSkeleton />
77	    ) : (
78	        <div className="col-span-12 flex justify-center py-8">
79	            <LoaderCircle className="animate-spin text-primary" />
80	        </div>
81	    );
82	
83	    /**
84	     * ==========>> STORE CONSTS <<==========
85	     */
86	    const isCoordenadorOrMaster = useBrokerStore((store) => store.isCoordenadorOrMaster);
87	    const setIsCoordenadorOrMaster = useBrokerStore((store) => store.setIsCoordenadorOrMaster);
88	    const userRole = useUserInfoStore((store) => store.data.role);
89	    const setExtratoId = useBrokerStore((store) => store.setExtratoId);
90	
91	    // ==============
92	    // # Data Hooks
93	    // ==============
94	    // useQuery (não suspense): 404/403 precisam renderizar UI local — useSuspenseQuery
95	    // lança no error boundary e ignora o tratamento abaixo.
96	    const {
97	        data: detailedExtratoData,
98	        isError: isErrorExtratoData,
99	        error: extratoDataError,
100	        isPending: isPendingExtratoData,
101	    } = useQuery(useExtratoDataQueryOptions(id));
102	
103	    const { data: linkedCedentesList } = useOficioLinkedCedentesQuery(id);
104	
105	    // ==============
106	    // # States
107	    // ==============
108	    const [pendingExigenciasCount, setPendingExigenciasCount] = useState<number>(0);
109	    const [conflictModalOpen, setConflictModalOpen] = useState(false);
110	    const userProfile = useCollaborationUserProfile();
111	    const currentUserId = useCollaborationCurrentUserId();
112	
113	    const handleCollabStateChanged = useCallback(
114	        (event: CollaborationStateChangedEvent) => {
115	            if (event.change_type === 'revision_conflict') {
116	                setConflictModalOpen(true);
117	                posthog.capture('collab_state_conflict_shown', {
118	                    resource_type: event.resource_type,
119	                    change_type: event.change_type,
120	                });
121	                return;
122	            }
123	
124	            handleExtratoCollaborationEvent(queryClient, id, event, currentUserId);
125	
126	            posthog.capture('collab_state_changed_received', {
127	                resource_type: 'extrato',
128	                change_type: event.change_type,
129	                section: event.payload?.section,
130	            });
131	        },
132	        [currentUserId, id],
133	    );
134	
135	    const collaboration = useResourceCollaboration({
136	        enabled: Boolean(id) && Boolean(detailedExtratoData),
137	        resourceType: 'extrato',
138	        resourceId: id,
139	        currentUserId,
140	        onStateChanged: handleCollabStateChanged,
141	    });
142	
143	    useEffect(() => {
144	        if (!collaboration.isConnected) return;
145	        posthog.capture('collab_session_started', { resource_type: 'extrato' });
146	    }, [collaboration.isConnected]);
147	
148	    // ==============
149	    // # Constants
150	    // ==============
151	    const currentProposalStatus = useMemo(
152	        () => detailedExtratoData?.propostas.find((p) => p.vigente)?.status,
153	        [detailedExtratoData],
154	    );
155	    const currentVigenteProposal = useMemo(
156	        () => detailedExtratoData?.propostas.find((p) => p.vigente),
157	        [detailedExtratoData],
158	    );
159	    const exigencias = currentVigenteProposal?.exigencias || [];
160	
161	    const isArchived = detailedExtratoData?.arquivado ?? false;
162	    const lockState = resolveOficioSectionLockState({
163	        isArchived,
164	        extratoStatus: detailedExtratoData?.status,
165	        proposalStatus: currentProposalStatus,
166	        hasCessionarioVinculado: hasCessionarioLink(linkedCedentesList),
167	    });
168	    const isLocked = lockState.isProposalLocked;
169	    const lockReason = lockState.proposalLockReason;
170	    const archivedDetails = useMemo(() => {
171	        if (!isArchived || !detailedExtratoData) return null;
172	
173	        const arquivamento = detailedExtratoData.ultimo_arquivamento;
174	        if (!arquivamento) return null;
175	
176	        return {
177	            mensagem: 'Este extrato foi arquivado e não pode ser editado.',
178	            ...arquivamento,
179	        };
180	    }, [detailedExtratoData, isArchived]);
181	    const canDisplayInfoForm = isCoordenadorOrMaster;
182	    const currentTenant = getTenantFromUrl();
183	    const oficioTenant = detailedExtratoData?.host;
184	    const isDueDiligenceInValidation = detailedExtratoData?.due_diligence?.some(
185	        (dd) => dd.status === 'VALIDACAO_PROPOSTA',
186	    );
187	
188	    const { data: accessibleHosts } = useSuspenseQuery<Host[]>({
189	        queryKey: [QueryKeys.host.accessible],
190	        queryFn: getAccessibleHosts,
191	    });
192	
193	    /**
194	     * ============>> USE EFFECT <<==========
195	     */
196	    useEffect(() => {
197	        setExtratoId(id);
198	        if (
199	            userRole === 'COMERCIAL_COORDENADOR' ||
200	            userRole === 'COMERCIAL_COORDENADOR_EXTERNO' ||
201	            isUserMasterOrDev(userRole)
202	        ) {
203	            setIsCoordenadorOrMaster(true);
204	        }
205	    }, [id, setExtratoId, userRole, setIsCoordenadorOrMaster]);
206	
207	    const hasNoAccess = useMemo(() => {
208	        if (!oficioTenant || !accessibleHosts) return false;
209	
210	        // Verifica se o host do ofício está na lista de hosts acessíveis do usuário
211	        const isHostAccessible = accessibleHosts.some(
212	            (h) => h.domain.toLocaleLowerCase() === oficioTenant.toLocaleLowerCase()
213	        );
214	
215	        return !isHostAccessible;
216	    }, [oficioTenant, accessibleHosts]);
217	
218	    // Tour: proposta vigente ausente ou zerada (hooks before any early return)
219	    const activeProposal = useMemo(() => {
220	        if (!detailedExtratoData?.propostas) return null;
221	        return detailedExtratoData.propostas.find((p) => p.vigente) || null;
222	    }, [detailedExtratoData]);
223	
224	    const hasZeroProposal = useMemo(() => {
225	        return isProposalSemSmartblock(activeProposal);
226	    }, [activeProposal]);
227	
228	    const shouldShowTour = useMemo(() => {
229	        return (!activeProposal || hasZeroProposal) && !isArchived;
230	    }, [activeProposal, hasZeroProposal, isArchived]);
231	
232	    if (isPendingExtratoData) {
233	        return isGerencialOficioDetail ? (
234	            <GerencialOficioSectionSkeleton />
235	        ) : (
236	            <OficioDetailsSkeleton />
237	        );
238	    }
239	
240	    if (isErrorExtratoData) {
241	        // Verificar se é erro 404 específico
242	        if (extratoDataError instanceof AxiosError && extratoDataError.response?.status === 404) {
243	            const backHref = isGerencialOficioDetail
244	                ? APP_ROUTES.private.gerencialBroker.name
245	                : APP_ROUTES.private.broker.name;
246	
247	            // R7-24: se o id não é um UUID válido, a URL é inválida (ex.: username
248	            // em vez de extrato ID). Mensagem confusa "Ofício não encontrado" →
249	            // "Endereço inválido" com explicação clara e próximo passo para o usuário.
250	            const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
251	            const isInvalidId = !UUID_RE.test(id);
252	            const alertTitle = isInvalidId ? 'Endereço inválido' : 'Ofício não encontrado';
253	            const alertMessage = isInvalidId
254	                ? 'O endereço que você acessou não corresponde a um ofício do Celer. ' +
255	                  'Isso pode acontecer quando o link vem de fora do sistema, de uma notificação ou foi copiado incorretamente. ' +
256	                  'Para continuar, abra o ofício pelo botão ou pela lista oficial dentro do Celer.'
257	                : 'Ofício não encontrado ou sem acesso. Verifique se o código está ' +
258	                  'correto ou se você tem permissão para visualizar este ofício.';
259	
260	            return (
261	                <div className="col-span-12 flex justify-center py-8">
262	                    <Alert className="max-w-md" variant="destructive">
263	                        <AlertTriangle className="h-4 w-4" />
264	                        <AlertTitle>{alertTitle}</AlertTitle>
265	                        <AlertDescription className="space-y-3">
266	                            <p>{alertMessage}</p>
267	                            <Button asChild variant="outline" size="sm" className="gap-1.5">
268	                                <Link href={backHref}>
269	                                    <ChevronLeft className="h-3.5 w-3.5" />
270	                                    Voltar
271	                                </Link>
272	                            </Button>
273	                        </AlertDescription>
274	                    </Alert>
275	                </div>
276	            );
277	        }
278	        return <RequestError />;
279	    }
280	
281	    if (!detailedExtratoData) {
282	        return <RequestError />;
283	    }
284	
285	    if (hasNoAccess) {
286	        return (
287	            <AccessErrorCard
288	                errorType="tenant"
289	                currentTenant={currentTenant}
290	                oficioTenant={oficioTenant}
291	            />
292	        );
293	    }
294	
295	    return (
296	        <>
297	            <CollaborationConflictModal
298	                open={conflictModalOpen}
299	                onDismiss={() => setConflictModalOpen(false)}
300	                onReload={() => {
301	                    setConflictModalOpen(false);
302	                    void queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.item, id] });
303	                }}
304	            />
305	            {detailedExtratoData && (
306	                <CollaborationProvider
307	                    value={buildCollaborationContextValue({
308	                        collaboration,
309	                        userProfile: userProfile,
310	                        showRevisionConflict: () => setConflictModalOpen(true),
311	                    })}
312	                >
313	                <div
314	                    className={cn(
315	                        'grid grid-cols-12',
316	                        isGerencialOficioDetail ? 'gap-4 md:gap-5' : 'gap-6',
317	                    )}
318	                >
319	                    {exigencias.length > 0 && (
320	                        <div className="col-span-12 flex justify-end">
321	                            <BrokerExigenciasViewer
322	                                exigencias={exigencias}
323	                                onPendingCountChange={setPendingExigenciasCount}
324	                            />
325	                        </div>
326	                    )}
327	                    {isArchived && (
328	                        isGerencialOficioDetail ? (
329	                            <div className="col-span-12">
330	                                <GerencialArchiveDetailsPanel
331	                                    title="Extrato arquivado"
332	                                    details={
333	                                        archivedDetails ?? {
334	                                            mensagem: 'Este extrato foi arquivado e não pode ser editado.',
335	                                        }
336	                                    }
337	                                />
338	                            </div>
339	                        ) : (
340	                        <Alert className="col-span-12" variant="destructive">
341	                            <Info size={20} />
342	                            <div className="mt-1 space-y-2">
343	                                <AlertTitle>Extrato Arquivado!</AlertTitle>
344	                                {archivedDetails ? (
345	                                    <>
346	                                        <BlockingArchiveDetails
347	                                            blockingInfo={archivedDetails}
348	                                            showContextFooter={false}
349	                                        />
350	                                        <p className="text-xs font-medium text-destructive/90">
351	                                            Para editar cedentes, documentos ou propostas, use o botão{' '}
352	                                            <span className="font-bold">Restaurar</span> no topo da página.
353	                                        </p>
354	                                    </>
355	                                ) : (
356	                                    <AlertDescription>
357	                                        Este extrato foi arquivado e não pode ser editado.
358	                                    </AlertDescription>
359	                                )}
360	                            </div>
361	                        </Alert>
362	                        )
363	                    )}
364	
365	                    <BrokerOficioDetailsHeader pendingExigenciasCount={pendingExigenciasCount} />
366	
367	                    {activeProposal && hasZeroProposal && !isArchived && (
368	                        <div className="col-span-12">
369	                            <SemSmartblockAlert variant="cta" />
370	                        </div>
371	                    )}
372	
373	                    <BrokerOficioStepper />
374	                    <BrokerOficioChecksSection />
375	                    <div
376	                        className={cn(
377	                            'relative col-span-12 grid grid-cols-12',
378	                            isGerencialOficioDetail ? 'gap-4 md:gap-5' : 'gap-6',
379	                        )}
380	                    >
381	                        <Suspense fallback={sectionFallback}>
382	                            <BrokerCedenteForm
383	                                isLocked={lockState.isCedenteLocked}
384	                                lockReason={lockState.cedenteLockReason}
385	                            />
386	                        </Suspense>
387	                        <Suspense fallback={sectionFallback}>
388	                            <BrokerSlider isLocked={isLocked && !isDueDiligenceInValidation} />
389	                        </Suspense>
390	                        <DocsSliderContextProvider>
391	                            <Suspense fallback={sectionFallback}>
392	                                <DocumentsSection
393	                                    className="lg:col-span-8"
394	                                    isLocked={lockState.isDocumentsLocked}
395	                                    lockReason={lockState.documentsLockReason}
396	                                />
397	                            </Suspense>
398	                        </DocsSliderContextProvider>
399	
400	                        {/* Proposal History */}

