'use client';
import { AccessErrorCard } from '@/components/Cards/AccessErrorCard';
import { BlockingArchiveDetails } from '@/components/BlockingArchiveDetails';
import { GerencialArchiveDetailsPanel } from '@/app/crm/gerencial-broker/_components/shared/GerencialArchiveDetailsPanel';
import { GerencialOficioSectionSkeleton } from '@/app/crm/gerencial-broker/_components/shared/GerencialOficioSectionSkeleton';
import {
    GERENCIAL_OFICIO_SECTION_CLASS,
    gerencialOficioSectionStyle,
} from '@/app/crm/gerencial-broker/_components/shared/GerencialOficioSectionCard';
import { useIsGerencialOficioDetail } from '@/app/crm/gerencial-broker/_hooks/useIsGerencialOficioDetail';
import { CollaborationConflictModal } from '@/components/Collaboration/CollaborationConflictModal';
import { CollaborationProvider } from '@/components/Collaboration/CollaborationContext';
import { buildCollaborationContextValue } from '@/components/Collaboration/build-collaboration-context-value';
import {
    useCollaborationCurrentUserId,
    useCollaborationUserProfile,
} from '@/components/Collaboration/use-collaboration-user';
import { BrokerOficioDetailsHeader } from '@/components/Header/BrokerOficioDetailsHeader';
import RequestError from '@/components/RequestError';
import { BrokerOficioChecksSection } from '@/components/Sections/Broker/BrokerOficioChecksSection';
import { OficioDetailsSkeleton } from '@/components/Skeletons/Broker/OficioDetailsSkeleton';
import { ProposalHistorySkeleton } from '@/components/Skeletons/Broker/ProposalHistorySkeleton';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { ProposalCreationTour } from '@/components/ui/proposal-creation-tour';
import { APP_ROUTES } from '@/constants/app-routes';
import { QueryKeys } from '@/constants/query-keys';
import { hasCessionarioLink } from '@/functions/broker/cedente-cession-percentage';
import { resolveOficioSectionLockState } from '@/functions/broker/oficio-lock-state';
import { DocsSliderContextProvider } from '@/context/DocsSliderContext';
import { handleExtratoCollaborationEvent } from '@/components/Collaboration/extrato-collaboration-sync';
import { isUserMasterOrDev } from '@/functions/rulesVerification';
import { useOficioLinkedCedentesQuery } from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { useResourceCollaboration } from '@/hooks/useResourceCollaboration';
import { getAccessibleHosts, Host } from '@/services/host';
import { useBrokerStore } from '@/store/useBroker';
import { useUserInfoStore } from '@/store/userInfo';
import { isProposalSemSmartblock } from '@/functions/propostas/is-proposal-sem-smartblock';
import type { CollaborationStateChangedEvent } from '@/types/collaboration';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import queryClient from '@/utils/queryClient';
import { useQuery, useSuspenseQuery } from '@tanstack/react-query';
import { AxiosError } from 'axios';
import { AlertTriangle, ChevronLeft, Info, LoaderCircle } from 'lucide-react';
import Link from 'next/link';
import { lazy, Suspense, useCallback, useEffect, useMemo, useState } from 'react';
import posthog from 'posthog-js';
import { BrokerExigenciasViewer } from './BrokerExigenciasViewer';
import BrokerOficioStepper from './BrokerOficioStepper';
import { BrokerCommentsSection } from './CommentsSection';
import {
    OFICIO_COMMENTS_PANEL_CLASS,
    OFICIO_COMMENTS_STICKY_ASIDE_CLASS,
} from './oficio-comments-sticky-layout';
import ProposalHistory from './ProposalHistory';
import { SemSmartblockAlert } from '@/components/CRM/Broker/SemSmartblockAlert';
import { cn } from '@/lib/utils';

// Lazy load heavy components
const BrokerCedenteForm = lazy(() => import('@/components/Forms/Broker/BrokerCedenteForm'));
const BrokerSlider = lazy(() => import('@/components/Sliders/BrokerSlider'));
const DocumentsSection = lazy(() =>
    import('@/app/crm/broker/[id]/_components/DocumentsSection').then((module) => ({ default: module.DocumentsSection })),
);
const ReadOnlyOficioInfoForm = lazy(() =>
    import('@/components/Forms/ReadOnlyOficioInfoForm').then((module) => ({
        default: module.ReadOnlyOficioInfoForm,
    })),
);
const NewEditOficioBrokerForm = lazy(() => import('@/components/Forms/NewEditOficioBrokerForm'));

export const BrokerOficioDetails = ({ id }: { id: string }) => {
    const isGerencialOficioDetail = useIsGerencialOficioDetail();
    const sectionFallback = isGerencialOficioDetail ? (
        <GerencialOficioSectionSkeleton />
    ) : (
        <div className="col-span-12 flex justify-center py-8">
            <LoaderCircle className="animate-spin text-primary" />
        </div>
    );

    /**
     * ==========>> STORE CONSTS <<==========
     */
    const isCoordenadorOrMaster = useBrokerStore((store) => store.isCoordenadorOrMaster);
    const setIsCoordenadorOrMaster = useBrokerStore((store) => store.setIsCoordenadorOrMaster);
    const userRole = useUserInfoStore((store) => store.data.role);
    const setExtratoId = useBrokerStore((store) => store.setExtratoId);

    // ==============
    // # Data Hooks
    // ==============
    // useQuery (não suspense): 404/403 precisam renderizar UI local — useSuspenseQuery
    // lança no error boundary e ignora o tratamento abaixo.
    const {
        data: detailedExtratoData,
        isError: isErrorExtratoData,
        error: extratoDataError,
        isPending: isPendingExtratoData,
    } = useQuery(useExtratoDataQueryOptions(id));

    const { data: linkedCedentesList } = useOficioLinkedCedentesQuery(id);

    // ==============
    // # States
    // ==============
    const [pendingExigenciasCount, setPendingExigenciasCount] = useState<number>(0);
    const [conflictModalOpen, setConflictModalOpen] = useState(false);
    const userProfile = useCollaborationUserProfile();
    const currentUserId = useCollaborationCurrentUserId();

    const handleCollabStateChanged = useCallback(
        (event: CollaborationStateChangedEvent) => {
            if (event.change_type === 'revision_conflict') {
                setConflictModalOpen(true);
                posthog.capture('collab_state_conflict_shown', {
                    resource_type: event.resource_type,
                    change_type: event.change_type,
                });
                return;
            }

            handleExtratoCollaborationEvent(queryClient, id, event, currentUserId);

            posthog.capture('collab_state_changed_received', {
                resource_type: 'extrato',
                change_type: event.change_type,
                section: event.payload?.section,
            });
        },
        [currentUserId, id],
    );

    const collaboration = useResourceCollaboration({
        enabled: Boolean(id) && Boolean(detailedExtratoData),
        resourceType: 'extrato',
        resourceId: id,
        currentUserId,
        onStateChanged: handleCollabStateChanged,
    });

    useEffect(() => {
        if (!collaboration.isConnected) return;
        posthog.capture('collab_session_started', { resource_type: 'extrato' });
    }, [collaboration.isConnected]);

    // ==============
    // # Constants
    // ==============
    const currentProposalStatus = useMemo(
        () => detailedExtratoData?.propostas.find((p) => p.vigente)?.status,
        [detailedExtratoData],
    );
    const currentVigenteProposal = useMemo(
        () => detailedExtratoData?.propostas.find((p) => p.vigente),
        [detailedExtratoData],
    );
    const exigencias = currentVigenteProposal?.exigencias || [];

    const isArchived = detailedExtratoData?.arquivado ?? false;
    const lockState = resolveOficioSectionLockState({
        isArchived,
        extratoStatus: detailedExtratoData?.status,
        proposalStatus: currentProposalStatus,
        hasCessionarioVinculado: hasCessionarioLink(linkedCedentesList),
    });
    const isLocked = lockState.isProposalLocked;
    const lockReason = lockState.proposalLockReason;
    const archivedDetails = useMemo(() => {
        if (!isArchived || !detailedExtratoData) return null;

        const arquivamento = detailedExtratoData.ultimo_arquivamento;
        if (!arquivamento) return null;

        return {
            mensagem: 'Este extrato foi arquivado e não pode ser editado.',
            ...arquivamento,
        };
    }, [detailedExtratoData, isArchived]);
    const canDisplayInfoForm = isCoordenadorOrMaster;
    const currentTenant = getTenantFromUrl();
    const oficioTenant = detailedExtratoData?.host;
    const isDueDiligenceInValidation = detailedExtratoData?.due_diligence?.some(
        (dd) => dd.status === 'VALIDACAO_PROPOSTA',
    );

    const { data: accessibleHosts } = useSuspenseQuery<Host[]>({
        queryKey: [QueryKeys.host.accessible],
        queryFn: getAccessibleHosts,
    });

    /**
     * ============>> USE EFFECT <<==========
     */
    useEffect(() => {
        setExtratoId(id);
        if (
            userRole === 'COMERCIAL_COORDENADOR' ||
            userRole === 'COMERCIAL_COORDENADOR_EXTERNO' ||
            isUserMasterOrDev(userRole)
        ) {
            setIsCoordenadorOrMaster(true);
        }
    }, [id, setExtratoId, userRole, setIsCoordenadorOrMaster]);

    const hasNoAccess = useMemo(() => {
        if (!oficioTenant || !accessibleHosts) return false;

        // Verifica se o host do ofício está na lista de hosts acessíveis do usuário
        const isHostAccessible = accessibleHosts.some(
            (h) => h.domain.toLocaleLowerCase() === oficioTenant.toLocaleLowerCase()
        );

        return !isHostAccessible;
    }, [oficioTenant, accessibleHosts]);

    // Tour: proposta vigente ausente ou zerada (hooks before any early return)
    const activeProposal = useMemo(() => {
        if (!detailedExtratoData?.propostas) return null;
        return detailedExtratoData.propostas.find((p) => p.vigente) || null;
    }, [detailedExtratoData]);

    const hasZeroProposal = useMemo(() => {
        return isProposalSemSmartblock(activeProposal);
    }, [activeProposal]);

    const shouldShowTour = useMemo(() => {
        return (!activeProposal || hasZeroProposal) && !isArchived;
    }, [activeProposal, hasZeroProposal, isArchived]);

    if (isPendingExtratoData) {
        return isGerencialOficioDetail ? (
            <GerencialOficioSectionSkeleton />
        ) : (
            <OficioDetailsSkeleton />
        );
    }

    if (isErrorExtratoData) {
        // Verificar se é erro 404 específico
        if (extratoDataError instanceof AxiosError && extratoDataError.response?.status === 404) {
            const backHref = isGerencialOficioDetail
                ? APP_ROUTES.private.gerencialBroker.name
                : APP_ROUTES.private.broker.name;

            // R7-24: se o id não é um UUID válido, a URL é inválida (ex.: username
            // em vez de extrato ID). Mensagem confusa "Ofício não encontrado" →
            // "Endereço inválido" com explicação clara e próximo passo para o usuário.
            const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
            const isInvalidId = !UUID_RE.test(id);
            const alertTitle = isInvalidId ? 'Endereço inválido' : 'Ofício não encontrado';
            const alertMessage = isInvalidId
                ? 'O endereço que você acessou não corresponde a um ofício do Celer. ' +
                  'Isso pode acontecer quando o link vem de fora do sistema, de uma notificação ou foi copiado incorretamente. ' +
                  'Para continuar, abra o ofício pelo botão ou pela lista oficial dentro do Celer.'
                : 'Ofício não encontrado ou sem acesso. Verifique se o código está ' +
                  'correto ou se você tem permissão para visualizar este ofício.';

            return (
                <div className="col-span-12 flex justify-center py-8">
                    <Alert className="max-w-md" variant="destructive">
                        <AlertTriangle className="h-4 w-4" />
                        <AlertTitle>{alertTitle}</AlertTitle>
                        <AlertDescription className="space-y-3">
                            <p>{alertMessage}</p>
                            <Button asChild variant="outline" size="sm" className="gap-1.5">
                                <Link href={backHref}>
                                    <ChevronLeft className="h-3.5 w-3.5" />
                                    Voltar
                                </Link>
                            </Button>
                        </AlertDescription>
                    </Alert>
                </div>
            );
        }
        return <RequestError />;
    }

    if (!detailedExtratoData) {
        return <RequestError />;
    }

    if (hasNoAccess) {
        return (
            <AccessErrorCard
                errorType="tenant"
                currentTenant={currentTenant}
                oficioTenant={oficioTenant}
            />
        );
    }

    return (
        <>
            <CollaborationConflictModal
                open={conflictModalOpen}
                onDismiss={() => setConflictModalOpen(false)}
                onReload={() => {
                    setConflictModalOpen(false);
                    void queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.item, id] });
                }}
            />
            {detailedExtratoData && (
                <CollaborationProvider
                    value={buildCollaborationContextValue({
                        collaboration,
                        userProfile: userProfile,
                        showRevisionConflict: () => setConflictModalOpen(true),
                    })}
                >
                <div
                    className={cn(
                        'grid grid-cols-12',
                        isGerencialOficioDetail ? 'gap-4 md:gap-5' : 'gap-6',
                    )}
                >
                    {exigencias.length > 0 && (
                        <div className="col-span-12 flex justify-end">
                            <BrokerExigenciasViewer
                                exigencias={exigencias}
                                onPendingCountChange={setPendingExigenciasCount}
                            />
                        </div>
                    )}
                    {isArchived && (
                        isGerencialOficioDetail ? (
                            <div className="col-span-12">
                                <GerencialArchiveDetailsPanel
                                    title="Extrato arquivado"
                                    details={
                                        archivedDetails ?? {
                                            mensagem: 'Este extrato foi arquivado e não pode ser editado.',
                                        }
                                    }
                                />
                            </div>
                        ) : (
                        <Alert className="col-span-12" variant="destructive">
                            <Info size={20} />
                            <div className="mt-1 space-y-2">
                                <AlertTitle>Extrato Arquivado!</AlertTitle>
                                {archivedDetails ? (
                                    <>
                                        <BlockingArchiveDetails
                                            blockingInfo={archivedDetails}
                                            showContextFooter={false}
                                        />
                                        <p className="text-xs font-medium text-destructive/90">
                                            Para editar cedentes, documentos ou propostas, use o botão{' '}
                                            <span className="font-bold">Restaurar</span> no topo da página.
                                        </p>
                                    </>
                                ) : (
                                    <AlertDescription>
                                        Este extrato foi arquivado e não pode ser editado.
                                    </AlertDescription>
                                )}
                            </div>
                        </Alert>
                        )
                    )}

                    <BrokerOficioDetailsHeader pendingExigenciasCount={pendingExigenciasCount} />

                    {activeProposal && hasZeroProposal && !isArchived && (
                        <div className="col-span-12">
                            <SemSmartblockAlert variant="cta" />
                        </div>
                    )}

                    <BrokerOficioStepper />
                    <BrokerOficioChecksSection />
                    <div
                        className={cn(
                            'relative col-span-12 grid grid-cols-12',
                            isGerencialOficioDetail ? 'gap-4 md:gap-5' : 'gap-6',
                        )}
                    >
                        <Suspense fallback={sectionFallback}>
                            <BrokerCedenteForm
                                isLocked={lockState.isCedenteLocked}
                                lockReason={lockState.cedenteLockReason}
                            />
                        </Suspense>
                        <Suspense fallback={sectionFallback}>
                            <BrokerSlider isLocked={isLocked && !isDueDiligenceInValidation} />
                        </Suspense>
                        <DocsSliderContextProvider>
                            <Suspense fallback={sectionFallback}>
                                <DocumentsSection
                                    className="lg:col-span-8"
                                    isLocked={lockState.isDocumentsLocked}
                                    lockReason={lockState.documentsLockReason}
                                />
                            </Suspense>
                        </DocsSliderContextProvider>

                        {/* Proposal History */}

