import { PageContainer } from '@/components/Layouts/PageContainer';
import { OficioDetailsSkeleton } from '@/components/Skeletons/Broker/OficioDetailsSkeleton';
import { fetchOficioOgMeta } from '@/lib/open-graph/fetch-resource-og';
import { resolveMetadataBase } from '@/lib/open-graph/resolve-metadata-base';
import { Metadata } from 'next';
import { headers } from 'next/headers';
import { Suspense, lazy } from 'react';

// Lazy load the main component
const BrokerOficioDetails = lazy(() =>
    import('@/components/CRM/Broker/BrokerOficioDetails').then((module) => ({
        default: module.BrokerOficioDetails,
    })),
);

export async function generateMetadata({
    params,
}: {
    params: Promise<{ id: string }>;
}): Promise<Metadata> {
    const { id } = await params;
    const og = await fetchOficioOgMeta(id);
    const headersList = await headers();
    const metadataBase = resolveMetadataBase(
        headersList.get('x-forwarded-host') || headersList.get('host'),
        headersList.get('x-forwarded-proto'),
    );

    return {
        metadataBase,
        title: og.title,
        description: og.description,
        category: 'Dashboard Broker',
        applicationName: 'CelerApp',
        openGraph: {
            title: og.title,
            description: og.description,
            type: 'website',
            locale: 'pt_BR',
            siteName: 'Celer',
        },
        twitter: {
            card: 'summary_large_image',
            title: og.title,
            description: og.description,
        },
    };
}

export default async function BrokerAssetDetailsPage({
    params,
}: {
    params: Promise<{ id: string }>;
}) {
    const { id } = await params;

    return (
        <PageContainer variant="wide">
            <Suspense fallback={<OficioDetailsSkeleton />}>
                <BrokerOficioDetails id={id} />
            </Suspense>
        </PageContainer>
    );
}

