import { CEDENTE_TAB_VIEWPORT_HEIGHT_CLASS } from '../_types/cedente-bento';
import { BrokerOficioDetailsRouteSkeleton } from './BrokerOficioDetailsRouteSkeleton';
import { cedenteBentoHeaderIconClass } from './bentoCedenteClasses';
import OficioDetailsInfo from './OficioDetailsInfo';

const CedentesInfoLazy = lazy(() => import('./CedentesInfo'));

const BROKER_TAB_ITEMS = [
    { value: 'overview', label: 'Visão geral', icon: LayoutDashboard },
    { value: 'cedentes-info', label: 'Cedente', icon: UserRound },
] as const;

interface OficioDetailsTabsProps {
    id: string;
}

export function OficioDetailsTabs({ id }: OficioDetailsTabsProps) {
    const { theme } = useBentoCockpitTheme();
    const [activeTab, setActiveTab] = useQueryState('tab', parseAsString.withDefault('overview'));
    const topNotchRef = useRef<HTMLDivElement>(null);
    useTopNotchClipPath({ notchRef: topNotchRef });

    // Start extrato fetch as soon as tabs mount (before child trees settle).
    useQuery(useExtratoDataQueryOptions(id));

    const { data: linkedCedentesList } = useQuery(createOficioLinkedCedentesOptions(id));

    const filteredLinkedCedentesList = useMemo(
        () => filterVisibleCedenteLinks(linkedCedentesList),
        [linkedCedentesList],
    );

    async function prefetchCedenteData(cedenteId: string) {
        queryClient.prefetchQuery({
            queryKey: [QueryKeys.cedentes.data, cedenteId],
            queryFn: () => getCedenteData(cedenteId),
        });
        queryClient.prefetchQuery({
            queryKey: [QueryKeys.cedentes.linkedEsteirasCedente, cedenteId],
            queryFn: () => getLinkedCedenteEsteiras(cedenteId),
        });
    }

    const setExtratoId = useBrokerStore((store) => store.setExtratoId);

    const [prevId, setPrevId] = useState<string | null>(null);
    if (id !== prevId) {
        setPrevId(id);
        setExtratoId(id);
    }

    useEffect(() => {
        posthog.capture('crm_broker_details_tab_changed', {
            extrato_id: id,
            tab: activeTab,
        });
    }, [activeTab, id]);

    useEffect(() => {
        if (filteredLinkedCedentesList && filteredLinkedCedentesList.length > 0) {
            prefetchCedenteData(filteredLinkedCedentesList[0].cedente.id);
        }
    }, [filteredLinkedCedentesList]);

    const isCedentesTab = activeTab === 'cedentes-info';

    return (
        <ResourceCollaborationShell
            resourceType="extrato"
            resourceId={id}
            presenceLabel="vendo este ofício"
        >
        <div
            className={cn(
                isCedentesTab &&
                    cn(
                        'flex min-h-0 flex-col overflow-hidden',
                        CEDENTE_TAB_VIEWPORT_HEIGHT_CLASS,
                    ),
            )}
        >
            <BrokerActivationOficioMarker />
            <AnimatedTabs
                id="oficio-details-tabs"
                value={activeTab}
                onValueChange={setActiveTab}
                defaultValue="overview"
                className={cn(isCedentesTab && 'flex min-h-0 flex-1 flex-col overflow-hidden')}
            >
            <div className="relative h-[42px] shrink-0">
                <div
                    ref={topNotchRef}
                    className="absolute inset-0"
                    style={{ background: theme.cardSolid }}
                />
                {/*
                  Mobile: Voltar no fluxo (não absolute) + tabs no espaço restante.
                  sm+: Voltar absolute à esquerda; tabs centralizadas na faixa.
                */}
                <div className="relative flex h-full items-center gap-2 px-3 sm:justify-center sm:gap-1.5 sm:px-0">
                    <Link
                        href={APP_ROUTES.private.brokerDashboard.name}
                        aria-label="Voltar ao dashboard do broker"
                        className={cn(
                            'group/back relative z-10 inline-flex shrink-0 items-center gap-1.5 sm:absolute sm:left-3 sm:gap-2',
                            'rounded-[10px] outline-none',
                            'transition-transform duration-200 ease-out active:scale-[0.98]',
                            'focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,#1c64f2_45%,transparent)]',
                            'focus-visible:ring-offset-2 focus-visible:ring-offset-(--bento-shell)',
                            'motion-reduce:transition-none motion-reduce:active:scale-100',
                            'after:absolute after:-inset-y-2 after:-inset-x-1 after:content-[""]',
                        )}
                    >
                        <span className={cn(cedenteBentoHeaderIconClass, 'relative size-7 sm:size-8')}>
                            <ArrowLeft
                                size={16}
                                strokeWidth={2.25}
                                aria-hidden
                                className="transition-transform duration-200 ease-out group-hover/back:-translate-x-0.5 motion-reduce:transition-none"
                            />
                        </span>
                        <span className="relative hidden text-[12px] font-semibold tracking-wide text-(--bento-text) sm:inline">
                            Voltar
                        </span>
                    </Link>
                    <div
                        className="flex min-w-0 flex-1 items-center justify-center gap-1 sm:flex-none sm:gap-1.5"
                        role="tablist"
                        aria-label="Seções do ofício"
                    >
                        {BROKER_TAB_ITEMS.map(({ value, label, icon: Icon }) => (
                            <button
                                key={value}
                                type="button"
                                role="tab"
                                aria-selected={activeTab === value}
                                onClick={() => setActiveTab(value)}
                                className={cn(
                                    'flex h-[28px] shrink-0 items-center gap-1 rounded-full px-2.5 text-[11px] font-semibold tracking-wide transition-all duration-200 sm:gap-1.5 sm:px-4 sm:text-[12px]',
                                    activeTab === value
                                        ? 'bg-[#1c64f2] text-white shadow-[0_0_24px_rgba(28,100,242,0.30)]'
                                        : 'text-(--bento-text-muted) hover:text-(--bento-text)',
                                )}
                            >
                                <Icon size={14} className="shrink-0 opacity-80" />
                                <span className="truncate">{label}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            <AnimatedTabsContent value="overview" className="mt-0">
                <Suspense fallback={<BrokerOficioDetailsRouteSkeleton />}>
                    <OficioDetailsInfo extratoId={id} setActiveTab={setActiveTab} />
                </Suspense>
            </AnimatedTabsContent>

            <AnimatedTabsContent value="cedentes-info" className={cn('mt-0', isCedentesTab && 'flex min-h-0 flex-1 flex-col overflow-hidden')}>
                <Suspense
                    fallback={
                        <div className="p-6 text-sm" style={{ color: theme.textMuted }}>
                            Carregando dados do cedente...
                        </div>
                    }
                >
                    <div className="h-full min-h-0 flex-1">
                        <CedentesInfoLazy />
                    </div>
                </Suspense>
            </AnimatedTabsContent>
        </AnimatedTabs>
        </div>
        </ResourceCollaborationShell>
    );
}

