'use client';

import { AccessErrorCard } from '@/components/Cards/AccessErrorCard';
import RequestError from '@/components/RequestError';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import { useQuery } from '@tanstack/react-query';
import { getAccessibleHosts, Host } from '@/services/host';
import { QueryKeys } from '@/constants/query-keys';
import { OficioDetailsCockpit } from './OficioDetailsCockpit';
import { resolveOficioHostAccess } from './resolve-oficio-host-access';

interface OficioDetailsInfoProps {
    extratoId: string;
    setActiveTab: (tab: string) => void;
}

const OficioDetailsInfo = ({ extratoId, setActiveTab }: OficioDetailsInfoProps) => {
    const { data: detailedExtratoData, isError: isErrorExtratoData } = useQuery(
        useExtratoDataQueryOptions(extratoId),
    );

    const {
        data: accessibleHosts,
        isLoading: isLoadingHosts,
        isError: isHostsError,
    } = useQuery<Host[]>({
        queryKey: [QueryKeys.host.accessible],
        queryFn: getAccessibleHosts,
    });

    const currentTenant = getTenantFromUrl();
    const oficioTenant = detailedExtratoData?.host;
    const hostAccessState = resolveOficioHostAccess({
        oficioTenant,
        accessibleHosts,
        isLoading: isLoadingHosts,
        hasError: isHostsError,
    });

    if (hostAccessState === 'denied') {
        return (
            <div className="p-4 lg:p-6">
                <AccessErrorCard
                    errorType="tenant"
                    currentTenant={currentTenant}
                    oficioTenant={oficioTenant}
                />
            </div>
        );
    }

    if (isErrorExtratoData || hostAccessState === 'error') return <RequestError />;

    // Extrato loaded but access check (hosts) still pending: show minimal guard
    // instead of blocking the entire Suspense boundary with a full skeleton.
    if (hostAccessState === 'loading') {
        return (
            <div className="text-muted-foreground flex h-32 items-center justify-center text-sm">
                Verificando acesso...
            </div>
        );
    }

    return <OficioDetailsCockpit extratoId={extratoId} setActiveTab={setActiveTab} />;
};

export default OficioDetailsInfo;

