                    y: 0,
                    opacity: 1,
                    filter: 'blur(0px)',
                    stagger: 0.045,
                    duration: 0.42,
                    ease: 'power3.out',
                    clearProps: 'opacity,transform,filter',
                },
            );
        },
        { scope: mountRef },
    );

    function cardProps(id: BrokerCedenteBentoCardId) {
        const style = getStaticGridStyle(id);
        const meta = CARD_META[id];

        return {
            id,
            title: meta.title,
            headerVariant: 'accent' as const,
            headerSubtitle: meta.subtitle,
            headerIcon: meta.icon,
            gridColumn: style.gridColumn,
            gridRow: style.gridRow,
            draggable: false as const,
        };
    }

    const scrollableContentClass = 'flex h-0 min-h-0 flex-1 flex-col overflow-hidden p-2';

    const cards = (
        <>
            <BrokerDetailsBentoCard
                {...cardProps('cedente-form')}
                contentClassName={scrollableContentClass}
            >
                <BrokerCedenteForm isLocked={isLocked} lockReason={lockReason} embeddedInBento />
            </BrokerDetailsBentoCard>

            <BrokerDetailsBentoCard
                {...cardProps('documents')}
                contentClassName={scrollableContentClass}
            >
                <DocsSliderContextProvider>
                    <DocumentsBentoPanel isLocked={isLocked} lockReason={lockReason} />
                </DocsSliderContextProvider>
            </BrokerDetailsBentoCard>
        </>
    );

    const contentById: Record<BrokerCedenteBentoCardId, ReactNode> = {
        'cedente-form': (
            <div className="flex h-full min-h-0 flex-col overflow-hidden">
                <BrokerCedenteForm isLocked={isLocked} lockReason={lockReason} embeddedInBento />
            </div>
        ),
        documents: (
            <div className="h-[min(32rem,60vh)] min-h-0 overflow-hidden">
                <DocsSliderContextProvider>
                    <DocumentsBentoPanel isLocked={isLocked} lockReason={lockReason} />
                </DocsSliderContextProvider>
            </div>
        ),
    };

    return (
        <div className="h-full min-h-0">
            <div ref={mountRef} className="relative hidden h-full min-h-0 overflow-hidden p-4 xl:block">
                <div
                    className="relative grid h-full min-h-0 w-full grid-cols-12 items-stretch"
                    style={{

