import '@/app/crm/broker-dashboard/broker-bento-theme.css';

import { PageContainer } from '@/components/Layouts/PageContainer';
import { APP_ROUTES } from '@/constants/app-routes';
import { cn } from '@/lib/utils';
import { Metadata } from 'next';
import { redirect } from 'next/navigation';
import { Suspense } from 'react';
import { resolveBrokerV4Enabled } from '../_helpers/resolve-broker-v4-enabled';
import { BrokerInicioView } from './_components/BrokerInicioView';
import { INICIO_CARD_SURFACE_CLASS } from './_constants/surfaces';

export const metadata: Metadata = {
    title: 'CelerApp | Início',
    description: 'Esteira, filtros e tabela de operações do broker.',
    category: 'CRM Broker',
    openGraph: {
        title: 'CelerApp | Início',
        description: 'Esteira, filtros e tabela de operações do broker.',
    },
    applicationName: 'CelerApp',
};

export default async function BrokerInicioPage() {
    // Início é o Broker 4.0: só com a flag de cutover (host + usuário). Sem ela, fica o Meu espaço.
    if (!(await resolveBrokerV4Enabled())) {
        redirect(APP_ROUTES.private.broker.name);
    }

    return (
        <PageContainer variant="wide">
            <Suspense fallback={<BrokerInicioFallback />}>
                <BrokerInicioView />
            </Suspense>
        </PageContainer>
    );
}

function BrokerInicioFallback() {
    return (
        <div
            className={cn(
                INICIO_CARD_SURFACE_CLASS,
                'px-4 py-10 text-center text-sm text-muted-foreground',
            )}
        >
            Carregando o início…
        </div>
    );
}

